<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import type { BackendController } from './use-backend.ts'
import { MODEL_SLOTS, RELATIONSHIP_MODEL_SLOT, GROWTH_MODEL_SLOT, GENERAL_GROWTH_MODEL_SLOT, ARTIFACT_OBSERVATION_MODEL_SLOT, ORDINARY_CONTINUITY_MODEL_SLOTS, type ModelSlot } from './api/configuration.ts'
import { useDisplayAlias } from './ui-preferences.ts'
import { useTheme } from './theme.ts'
import { HTTPS_REQUIRED_MESSAGE } from './api/client.ts'
import SetupPanel from './SetupPanel.vue'
import CreatorConfigurationPanel from './CreatorConfigurationPanel.vue'
import OwnerProjectContextPanel from './OwnerProjectContextPanel.vue'
import GeneralGrowthOwnerPanel from './GeneralGrowthOwnerPanel.vue'
import SingleEventGrowthOwnerPanel from './SingleEventGrowthOwnerPanel.vue'
import SelfViewPanel from './SelfViewPanel.vue'
import Beta1OwnerPanel from './Beta1OwnerPanel.vue'

const props=defineProps<{backend:BackendController}>()
const configuration=props.backend.configuration,state=computed(()=>configuration.state),theme=useTheme(),display=useDisplayAlias()
const aliasDraft=ref(display.alias.value),group=ref('basic')
const maintenance=props.backend.inspectionMaintenance
const maintenanceScope=ref(props.backend.state.scope),migrationRoots=ref(''),migrationWholeNamespace=ref(false),migrationDiscovery=ref(false),migrationResume=ref(false),migrationOriginal=ref('')
const deadlineText=ref(new Date(Date.now()+30*60*1000-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16))
watch(()=>props.backend.state.scope,value=>{maintenanceScope.value=value;migrationRoots.value='';migrationWholeNamespace.value=false;migrationDiscovery.value=false;migrationResume.value=false;migrationOriginal.value=''})
const migrationStates:Record<string,string>={unknown:'受理或运行结果待确认',accepted:'维护已受理',running:'维护执行中',completed:'维护已确认完成',held:'维护 HOLD'}
const migrationPhases:Record<string,string>={accepted:'已受理',pausing:'正在暂停',paused:'已暂停',migrating:'正在迁移',migration_complete:'迁移已到 EOF',resuming:'正在恢复',active:'Host 已恢复 active',held:'HOLD'}
async function acceptMigration(){
  const refs=migrationWholeNamespace.value?[]:migrationRoots.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean).sort()
  await maintenance.accept({scope_kind:migrationWholeNamespace.value?'namespace_source_family':'exact_parent_closed_targets',target_refs:refs,
    deadline_utc:new Date(deadlineText.value).getTime()/1000,interpretation_status_discovery:migrationDiscovery.value,resume_on_complete:migrationResume.value})
}
const groups=[{id:'basic',label:'基本'},{id:'models',label:'模型策略'},{id:'persona',label:'角色与场景'},{id:'world',label:'世界与时间'},{id:'habit',label:'习惯'},{id:'long_window',label:'长期计划'},{id:'attention',label:'注意与表达'},{id:'memory',label:'记忆与关系'},{id:'life',label:'Life 与联系'},{id:'resources',label:'资源与安装'}]
const labels:Record<ModelSlot,string>={reply:'主回复',encode:'记忆编码',context_reply:'上下文回复',natural_generation:'自然生成',natural_review:'自然复核',appraisal:'感受评估',d07_cognition:'认知',contact_generation:'联系生成',contact_review:'联系复核',life_content:'Life 内容',life_numeric:'Life Numeric'}
const namedAuxiliarySlots=[{slot:RELATIONSHIP_MODEL_SLOT,label:'关系认知'},{slot:GROWTH_MODEL_SLOT,label:'成长认知'},{slot:GENERAL_GROWTH_MODEL_SLOT,label:'通用成长认知'},{slot:ARTIFACT_OBSERVATION_MODEL_SLOT,label:'Artifact 独立观察认知'},{slot:ORDINARY_CONTINUITY_MODEL_SLOTS[0],label:'普通连续性筛查'},{slot:ORDINARY_CONTINUITY_MODEL_SLOTS[1],label:'普通累计深复核'}] as const
const installedAuxiliarySlots=computed(()=>namedAuxiliarySlots.filter(item=>state.value.data?.model_slots.some(row=>row.slot===item.slot)))
const modelStates={selected:'已选择，尚未安装匹配',pending:'待选择或安装匹配',installed:'与已安装模型身份匹配'}
const options=computed(()=>state.value.data?.installed_policy.provider_options??[])
function select(slot:ModelSlot|'auxiliary',event:Event){configuration.selectModel(slot,(event.target as HTMLSelectElement).value)}
function selected(slot:ModelSlot){return slot==='reply'?state.value.draft?.llm_provider_id??'':state.value.draft?.model_selection.overrides[slot]??''}
function unavailable(providerId:string){return !!providerId&&!options.value.some(option=>option.provider_id===providerId)}
function changeGroup(id:string){if(group.value===id)return;props.backend.setup.invalidate();group.value=id}
const gaps:Record<string,string[]>={persona:['旧人格 genesis 付费开关不迁为自动调用；人格由真实 typed draft 和 Owner 采用链路管理。'],attention:['首句流式、补刀、夜间 typing、proactive 桥和 emotion 桥没有当前可消费的配置协议。此处不提供无效开关。'],memory:['旧 recall mode 与 Embedding SDK 配置尚无当前安装/读取协议，不把 chat Provider 选择冒充 Embedding 能力。'],life:['旧 Qzone、Cookie 与原始 Owner ID 不作为普通文本配置；Contact、Numeric、C09、D04 原门槛保留。']}
onBeforeUnmount(()=>{configuration.invalidate();props.backend.creator.invalidate();props.backend.setup.invalidate()})
</script>
<template>
  <section class="configuration-panel" aria-label="完整当前配置" :aria-busy="configuration.reading.value||configuration.writing.value">
    <header class="configuration-heading"><div><p class="configuration-code">CURRENT CONFIGURATION / BETA1</p><h3>高级配置</h3><p>本机保存目标、启动值、模型安装匹配与角色方案分别核验。显示偏好仅作用于当前浏览器。</p></div><button class="configuration-action" :disabled="!configuration.canRead.value" @click="configuration.read">{{configuration.reading.value?'正在读取实际配置…':'读取当前配置'}}</button></header>
    <p v-if="backend.requiresHttps.value" class="configuration-message" role="status">{{HTTPS_REQUIRED_MESSAGE}}</p>
    <nav class="configuration-tabs" aria-label="设置分组"><button v-for="item in groups" :key="item.id" :aria-current="group===item.id?'page':undefined" @click="changeGroup(item.id)">{{item.label}}</button></nav>
    <p v-if="state.message" class="configuration-message" :role="['error','conflict','unknown'].includes(state.status)?'alert':'status'">{{state.message}}</p>
    <section v-if="group==='basic'" class="configuration-section">
      <h4>本机配置与浏览器显示</h4>
      <div class="configuration-field"><label for="configuration-host-enabled">本机 Host 保存目标</label><select id="configuration-host-enabled" :value="state.draft?String(state.draft.enabled):''" :disabled="!configuration.canEdit.value" @change="configuration.setBasic('enabled',($event.target as HTMLSelectElement).value==='true')"><option v-if="!state.draft" value="">当前值未读取</option><option value="false">关闭（false）</option><option value="true">启用（true）</option></select><p v-if="state.data">本次启动：{{state.data.startup_values.enabled?'启用':'关闭'}}。本机 enabled 不代替 Authority 许可。</p></div>
      <div class="configuration-field"><label for="configuration-profile">Authority 配置档案选择</label><input id="configuration-profile" :value="state.draft?.authority_profile??''" maxlength="64" :disabled="!configuration.canEdit.value" autocomplete="off" spellcheck="false" @input="configuration.setBasic('authority_profile',($event.target as HTMLInputElement).value)"><p>这是本机档案选择，不创建配对或扩展授权。{{state.data?'本次启动：'+state.data.startup_values.authority_profile:''}}</p></div>
      <div class="configuration-field"><label for="configuration-display-alias">浏览器显示别名</label><input id="configuration-display-alias" v-model="aliasDraft" maxlength="80" autocomplete="off" spellcheck="false"><button class="configuration-action" @click="display.set(aliasDraft)">应用显示别名</button><p>仅替换本页“所有者工作台”的显示标签，实际已消费；不是 D01 人格名称，不写入角色方案或身份。</p></div>
      <div class="configuration-field"><label for="configuration-theme">浏览器主题</label><select id="configuration-theme" :value="theme.preference.value" @change="theme.setPreference(($event.target as HTMLSelectElement).value)"><option value="system">跟随系统</option><option value="light">浅色</option><option value="dark">深色</option></select><p>与页脚主题使用同一实际控制器。本地存储仅包含主题和显示别名。</p></div>
    </section>
    <section v-else-if="group==='models'" class="configuration-section">
      <h4>模型策略与已安装状态</h4><p>选项来自实际 SDK 已加载且启用的 chat Provider。配置保存不是模型授权；空覆盖不由前端自动补主模型。实际解析与安装匹配显示在各槽下方。</p>
      <div class="configuration-field"><label for="configuration-auxiliary">共享辅助 Provider</label><select id="configuration-auxiliary" :value="state.draft?.model_selection.auxiliary_provider_id??''" :disabled="!configuration.canEdit.value" @change="select('auxiliary',$event)"><option value="">{{state.draft?'未单独配置辅助模型':'当前值未读取'}}</option><option v-if="unavailable(state.draft?.model_selection.auxiliary_provider_id??'')" :value="state.draft?.model_selection.auxiliary_provider_id" disabled>当前保存但不在可用 SDK 清单：{{state.draft?.model_selection.auxiliary_provider_id}}</option><option v-for="option in options" :key="option.provider_id" :value="option.provider_id">{{option.provider_id}} · {{option.model_id}}</option></select></div>
      <div v-for="slot in MODEL_SLOTS" :key="slot" class="configuration-model-row"><div class="configuration-field"><label :for="'configuration-slot-'+slot">{{labels[slot]}} <small>{{slot}}</small></label><select :id="'configuration-slot-'+slot" :value="selected(slot)" :disabled="!configuration.canEdit.value" @change="select(slot,$event)"><option value="">{{!state.draft?'当前值未读取':slot==='reply'?'未选择主模型':'未单独覆盖；以服务端实际解析为准'}}</option><option v-if="unavailable(selected(slot))" :value="selected(slot)" disabled>当前保存但不在可用 SDK 清单：{{selected(slot)}}</option><option v-for="option in options" :key="option.provider_id" :value="option.provider_id">{{option.provider_id}} · {{option.model_id}}</option></select></div><template v-for="row in state.data?.model_slots.filter(item=>item.slot===slot)??[]" :key="row.slot"><p>{{modelStates[row.state]}} · {{row.reason_code}}</p><dl><div><dt>实际观察</dt><dd>{{row.selected_provider_id??'未选择'}} / {{row.model_id??'未观察到模型'}}</dd></div><div><dt>安装绑定</dt><dd>{{row.installed?row.installed.provider_id+' / '+row.installed.model_id:'未安装该槽'}}</dd></div><div v-if="row.installed"><dt>已安装输出上限</dt><dd>{{row.installed.max_output_tokens}} tokens</dd></div></dl></template></div>
      <div v-for="slot in installedAuxiliarySlots" :key="slot.slot" class="configuration-model-row">
        <h5>{{slot.label}} <small>{{slot.slot}}</small></h5><p>此正式槽使用上方共享辅助 Provider，与当前安装身份逐项匹配；没有独立覆盖键。保存选择后仍需正式安装匹配。</p>
        <template v-for="row in state.data?.model_slots.filter(item=>item.slot===slot.slot)??[]" :key="row.slot">
          <p>{{modelStates[row.state]}} · {{row.reason_code}}</p><dl><div><dt>实际观察</dt><dd>{{row.selected_provider_id??'未选择'}} / {{row.model_id??'未观察到模型'}}</dd></div><div><dt>安装绑定</dt><dd>{{row.installed?row.installed.provider_id+' / '+row.installed.model_id:'未安装该槽'}}</dd></div><div v-if="row.installed"><dt>已安装输出上限</dt><dd>{{row.installed.max_output_tokens}} tokens</dd></div></dl>
        </template>
      </div>
    </section>
    <section v-else-if="group==='resources'" class="configuration-section"><h4>资源、安装与启动许可</h4><dl v-if="state.data" class="configuration-resource-facts"><div><dt>当前安装</dt><dd>{{state.data.installed_policy.installation_id??'未观察到安装'}}</dd></div><div><dt>已安装档案</dt><dd>{{state.data.installed_policy.profile_id??'未观察到注册档案'}}</dd></div><div><dt>Workflow 版本</dt><dd>{{state.data.installed_policy.workflow_version??'未安装模型工作流'}}</dd></div><div><dt>已配置模型槽</dt><dd>{{state.data.installed_policy.configured_model_slots.join('、')||'无已安装槽'}}</dd></div></dl><p>安装限制只读，不能在本页增加 budget、延长 grant、伪造配对或解除 HOLD。Authority enabled 的独立管理操作见下方真实授权设置。</p><SetupPanel :backend="backend" /></section>
    <section v-else-if="group==='world'||group==='habit'||group==='long_window'" class="configuration-section"><Beta1OwnerPanel :backend="backend" :domain="group as 'world'|'habit'|'long_window'"/></section>
    <section v-else class="configuration-section"><h4>{{groups.find(item=>item.id===group)?.label}}</h4><p>领域配置通过当前 Owner 的方案草稿保存与编译/预览/采用链路，草稿不等于已采纳运行值。</p><CreatorConfigurationPanel :backend="backend" :group="group" /><OwnerProjectContextPanel v-if="group==='life'" :backend="backend"/><SelfViewPanel v-if="group==='persona'" :backend="backend"/><Beta1OwnerPanel v-if="group==='persona'" :backend="backend" domain="self"/><GeneralGrowthOwnerPanel v-if="group==='persona'" :backend="backend"/><SingleEventGrowthOwnerPanel v-if="group==='persona'" :backend="backend"/><ul class="configuration-gaps"><li v-for="gap in gaps[group]??[]" :key="gap">{{gap}}</li></ul></section>
    <section v-if="group==='memory'" class="configuration-section inspection-maintenance" aria-labelledby="inspection-maintenance-title" :aria-busy="maintenance.active.value">
      <h4 id="inspection-maintenance-title">旧来源记录维护</h4>
      <p>在 Host 仍在线时明确受理一次维护。后台会按固定范围与期限执行暂停、迁移，以及你预先授权的恢复；每阶段仍核验当前 Owner 和实际条件。</p>
      <p>整体暂停会使本页暂时断开。受理后不要重新提交；网络恢复后只查询原操作。失败、结果未知或到期将保持 HOLD，后台不自动重跑；本页不提供 Host 离线时的故障恢复入口。</p>
      <div class="configuration-field"><label for="inspection-scope">当前 Owner 维护范围</label><input id="inspection-scope" v-model="maintenanceScope" maxlength="192" placeholder="bot/persona" autocomplete="off" spellcheck="false" :disabled="maintenance.active.value"><button class="configuration-action" :disabled="maintenance.active.value||backend.state.busy||!maintenanceScope.trim()" @click="backend.setScope(maintenanceScope)">应用维护范围</button></div>
      <p>本次范围：{{backend.state.scope||'尚未选择'}}。受理由后端核验当前 read、maintain、control 权限；独立维护会话不开放来源正文。</p>
      <template v-if="!maintenance.attempt.value">
        <div class="configuration-field"><label for="inspection-roots">精确目标引用（每行一个，最多 32 个）</label><textarea id="inspection-roots" v-model="migrationRoots" rows="5" spellcheck="false" :disabled="maintenance.active.value||migrationWholeNamespace" aria-describedby="inspection-roots-hint"></textarea><p id="inspection-roots-hint">填写实际 memory.source 或 memory.interpretation 完整引用。服务端核验同一 namespace 及完整父闭包。</p></div>
        <label class="inspection-choice"><input v-model="migrationWholeNamespace" type="checkbox" :disabled="maintenance.active.value">明确选择整个当前 namespace 的来源家族</label>
        <label class="inspection-choice"><input v-model="migrationDiscovery" type="checkbox" :disabled="maintenance.active.value">明确允许发现所选 Interpretation 的当前状态</label>
        <label class="inspection-choice"><input v-model="migrationResume" type="checkbox" :disabled="maintenance.active.value">预先授权：迁移成功后按同一暂停原件恢复 Host</label>
        <p v-if="!migrationResume">未选择自动恢复：成功完成迁移后仍保持暂停，须使用正式运维恢复入口；本页可能保持离线。</p>
        <div class="configuration-field"><label for="inspection-deadline">原请求截止时间（本地时间，未来一小时内）</label><input id="inspection-deadline" v-model="deadlineText" type="datetime-local" :disabled="maintenance.active.value"><p>实际有效期限由后端按当前授权与资源限制收窄，受理后不能通过本页续期。</p></div>
        <button class="configuration-action" :disabled="!maintenance.canRequest.value" @click="acceptMigration">确认范围并一次受理暂停、迁移与恢复选择</button>
        <div class="configuration-field"><label for="inspection-original">查询已有维护原操作 UUID</label><input id="inspection-original" v-model="migrationOriginal" maxlength="36" autocomplete="off" spellcheck="false" :disabled="maintenance.active.value"><button class="configuration-action" :disabled="!maintenance.canRequest.value||!migrationOriginal.trim()" @click="maintenance.read(migrationOriginal)">只查询原操作并恢复固定输入</button></div>
      </template>
      <article v-if="maintenance.attempt.value" class="configuration-resource-facts">
        <h5>{{migrationStates[maintenance.attempt.value.status]}}</h5><p>维护原操作 UUID：{{maintenance.attempt.value.operation_id}}</p>
        <template v-if="maintenance.attempt.value.input"><p>暂停原操作 UUID：{{maintenance.attempt.value.input.pause_operation_id}}</p><p>恢复原操作 UUID：{{maintenance.attempt.value.input.resume_operation_id??'未预先授权恢复'}}</p><p>范围：{{maintenance.attempt.value.input.scope_kind==='namespace_source_family'?'整个当前 namespace 来源家族':'精确目标父闭包'}} · 目标 {{maintenance.attempt.value.input.target_refs.length}} 个</p><pre v-if="maintenance.attempt.value.input.target_refs.length">{{maintenance.attempt.value.input.target_refs.join('\n')}}</pre><p>原请求期限：{{new Date(maintenance.attempt.value.input.deadline_utc*1000).toLocaleString()}} · Interpretation 状态发现：{{maintenance.attempt.value.input.interpretation_status_discovery?'已明确允许':'未允许'}}</p></template>
        <template v-if="maintenance.attempt.value.view"><p>实际阶段：{{migrationPhases[maintenance.attempt.value.view.phase]}} · 实际有效期限：{{new Date(maintenance.attempt.value.view.effective_deadline_utc*1000).toLocaleString()}}</p><p v-if="maintenance.attempt.value.view.hold_code">HOLD：{{maintenance.attempt.value.view.hold_code}}</p></template>
        <dl v-if="maintenance.attempt.value.view?.progress"><div><dt>迁移阶段</dt><dd>{{maintenance.attempt.value.view.progress.local_phase??maintenance.attempt.value.view.progress.phase}}</dd></div><div><dt>已提交批次序号</dt><dd>{{maintenance.attempt.value.view.progress.batch_index<0?'尚无':maintenance.attempt.value.view.progress.batch_index}}</dd></div><div><dt>已迁移 / 已退役</dt><dd>{{maintenance.attempt.value.view.progress.migrated}} / {{maintenance.attempt.value.view.progress.retired}}</dd></div><div><dt>实际游标</dt><dd>{{maintenance.attempt.value.view.progress.cursor||'尚无已提交游标'}}</dd></div></dl>
        <button class="configuration-action" :disabled="!maintenance.canRequest.value" @click="maintenance.read(maintenance.attempt.value.operation_id)">只查询此原维护操作</button>
        <button v-if="maintenance.attempt.value.status==='completed'" class="configuration-action" :disabled="!maintenance.canRequest.value" @click="maintenance.newOperation">原维护已确认完成，准备新的维护</button>
      </article>
      <p v-if="maintenance.message.value" role="status" aria-live="polite">{{maintenance.message.value}}</p>
      <p>来源 metadata 的维护完成不等于来源正文授权。仅在后端确认迁移 EOF，且已选择恢复时再确认 Host active，才显示完成；随后仍须手动独立重读来源。</p>
    </section>
    <footer class="configuration-save"><div><p>仅保存本机四项真实配置及模型选择，{{state.data?.apply_semantics??'需先读取'}}。未保存领域方案或执行模型。</p><p v-if="configuration.dirty.value">存在未保存本机配置修改。</p><p v-if="state.operationId">当前操作：{{state.operationId}}</p></div><div><button class="configuration-action" :disabled="!configuration.canEdit.value||!configuration.dirty.value" @click="configuration.resetDraft">撤销本地草稿</button><button class="configuration-action" :disabled="!configuration.canSave.value" @click="configuration.save">{{state.status==='verifying'?'正在独立回读…':configuration.writing.value?'正在保存…':'保存本机配置并回读'}}</button></div></footer>
  </section>
</template>
